grid[8].append(7)
# 4-connected components of all non-7 cells
from collections import deque
R,C=16,16
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]!=7 and (r,c) not in seen:
   q=deque([(r,c)]); seen.add((r,c)); cells=[]
   while q:
    x,y=q.popleft(); cells.append((x,y))
    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=nx<R and 0<=ny<C and grid[nx][ny]!=7 and (nx,ny) not in seen:
      seen.add((nx,ny)); q.append((nx,ny))
   comps.append(cells)
for i,cells in enumerate(comps):
 vals=sorted({grid[r][c] for r,c in cells})
 print(i,len(cells), (min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells)), vals)

key={2,5,8}
selected=[]
for i,cells in enumerate(comps):
 vals={grid[r][c] for r,c in cells}
 if key <= vals:
  selected.append(i)
print('selected', selected)
out=[row.copy() for row in grid]
for i in selected:
 for r,c in comps[i]: out[r][c]=7
print('\n'.join(' '.join(map(str,row)) for row in out))
